import torch

def run(x, high):
    return torch.randint_like(x, high)

def valid(ref_outputs, sol_outputs, inputs, ctx):
    high = ctx['high']
    sol = sol_outputs[0]
    all_in_range = torch.logical_and(sol >= 0, sol < high).all().item()
    if not all_in_range:
        return {'passed': False, 'message': f'Values not in [0, {high})', 'metrics': {}}
    no_nan = not torch.isnan(sol).any().item()
    no_inf = not torch.isinf(sol).any().item()
    if not no_nan or not no_inf:
        return {'passed': False, 'message': 'Output contains NaN or Inf', 'metrics': {}}
    return {'passed': True, 'message': 'Statistical checks passed', 'metrics': {}}
